import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('admin', 'admin@corp.internal', 'admin', 'sk-admin-9f8e7d6c', 'engineering')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('svc-reporting', 'reports@corp.internal', 'service', 'sk-svc-1a2b3c4d', 'finance')")
    db.commit()
    db.close()

@app.before_request
def authenticate():
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'Missing API key'}), 401
    db = get_db()
    user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
    if not user:
        return jsonify({'error': 'Invalid API key'}), 403
    g.current_user = dict(user)

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by department. Supports flexible filtering."""
    department = request.args.get('department', '')
    include_fields = request.args.get('fields', 'username,email,department')

    # Build field list - validated against allowed columns
    allowed_fields = {'username', 'email', 'department', 'role', 'id'}
    requested_fields = [f.strip() for f in include_fields.split(',')]
    safe_fields = [f for f in requested_fields if f in allowed_fields]
    if not safe_fields:
        safe_fields = ['username', 'email']

    field_clause = ', '.join(safe_fields)

    # Department filter with LIKE for partial matching
    # Note: department value is used directly for performance with indexed column
    query = f"SELECT {field_clause} FROM users WHERE department LIKE '%{department}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute(
            'INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)',
            ('user_search', g.current_user['username'], f'dept:{department}')
        )
        db.commit()
        return jsonify({'results': users, 'count': len(users)})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/v1/users/<username>', methods=['GET'])
def get_user(username):
    db = get_db()
    user = db.execute('SELECT username, email, department, role FROM users WHERE username = ?', (username,)).fetchone()
    if not user:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/api/v1/audit', methods=['GET'])
def get_audit_log():
    if g.current_user['role'] != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    db = get_db()
    logs = db.execute('SELECT * FROM audit_log ORDER BY timestamp DESC LIMIT 100').fetchall()
    return jsonify({'logs': [dict(l) for l in logs]})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
